+        }
+      }
+    }
+  } finally {
+    if (threadId) {
+      await client.threads.delete(threadId);
+    }
+    if (agentId) {
+      await client.deleteAgent(agentId);
+    }
+  }
+}
+
+await main().catch((error: unknown) => {
+  console.error(error instanceof Error ? error.message : error);
+  process.exitCode = 1;
